(function(){const t=document.createElement("link").relList;if(t&&t.supports&&t.supports("modulepreload"))return;for(const o of document.querySelectorAll('link[rel="modulepreload"]'))i(o);new MutationObserver(o=>{for(const a of o)if(a.type==="childList")for(const r of a.addedNodes)r.tagName==="LINK"&&r.rel==="modulepreload"&&i(r)}).observe(document,{childList:!0,subtree:!0});function n(o){const a={};return o.integrity&&(a.integrity=o.integrity),o.referrerPolicy&&(a.referrerPolicy=o.referrerPolicy),o.crossOrigin==="use-credentials"?a.credentials="include":o.crossOrigin==="anonymous"?a.credentials="omit":a.credentials="same-origin",a}function i(o){if(o.ep)return;o.ep=!0;const a=n(o);fetch(o.href,a)}})();const en={en:{metaTitle:"Women’s economic autonomy in the Dutch Republic and maritime-induced male absence · Take Watanabe",metaDescription:"This thesis studies the causal effect of maritime-induced male absence on women’s economic autonomy in the early-modern Dutch Republic.",navAria:"Chapters",langAria:"Language",navMenuOpen:"Open section menu",navMenuClose:"Close section menu",navBrand:"Take Watanabe",navTitle:"Women’s economic autonomy in the Dutch Republic and maritime-induced male absence",navSetting:"Introduction",navQuestion:"Research question",navObserve:"Conceptual framework and data sources",navIntensity:"Data and treatment intensity",navCompare:"Empirical strategy",navEstimates:"Results",navFragile:"Robustness checks",navRead:"Discussion and conclusion",heroBrand:"Take Watanabe",heroTitle:"Women’s economic autonomy in the Dutch Republic and maritime-induced male absence",heroLede:"This thesis provides supportive evidence for the hypothesis that women’s economic autonomy in the Dutch Republic was positively affected by maritime-induced male absence.",heroBegin:"Follow the evidence",heroPdf:"Download PDF",heroFindingsAria:"What the evidence suggests",heroFindingsEyebrow:"Abstract",heroEstimateAria:"2.84 percentage points: estimated smaller literacy gender gap by 1750 per one standard deviation higher VOC departure intensity, with geography controls",heroEstimateNumber:"2.84",heroEstimateUnit:"pp",heroEstimateLabel:"Decrease in the literacy gender gap per 1 SD increase in seafarer departures",heroEstimateQualifier:"1750 · controlling for longitude and latitude",heroFemaleAria:"99.4 percent of the treatment effect on the gender gap in 1750 is accounted for by female literacy",heroFemaleNumber:"99.4%",heroFemaleLabel:"of the treatment effect via female literacy",heroSampleAria:"32 cities and 96 city-years in the sample",heroSampleLabel:"cities · 96 city-years",heroCaveatAria:"The results are highly robust to population growth controls and less robust to a leave-one-out test",heroCaveatLabel:"Robustness",heroCaveatText:"The results are highly robust to population growth controls and less robust to a leave-one-out test.",settingEyebrow:"Introduction",settingH2:"The rise of the Dutch Republic in the 17th century",settingP1:"The rise of the Dutch Republic in the 17th century marked a large increase in the relative importance of the maritime trading sector, where long and high-mortality voyages carried out by the Dutch East India Company (VOC) were necessary to both fund the independence war against the Spanish Empire and contest Spanish and Portuguese dominance in these areas, later creating the basis for the Dutch Golden Age.",globeAlt:"Interactive globe of reconstructed VOC sailing corridors and documented voyages",globeCaption:"Selected VOC connections in the seventeenth and eighteenth centuries. Ports are source-backed; lines between them reconstruct historically attested sailing corridors rather than exact ship tracks.",globeMetaWorld:"World · 17th–18th c.",globeMetaProjection:"Orthographic",globeInstruction:"Drag horizontally to rotate · use arrow keys when focused",globeRoutesLabel:"Select a route",globePause:"Pause rotation",globeResume:"Resume rotation",globeZoomIn:"Zoom in",globeZoomOut:"Zoom out",globeTypeCorridor:"Recurring corridor",globeTypeVoyage:"Documented voyage",globePeriodLabel:"Period",globeStopsLabel:"Documented places",globeSourcesLabel:"Historical sources",globeReconstruction:"Route note: documented places are joined through reconstructed sailing waypoints informed by period routes and prevailing winds; the line is not a surviving day-by-day track.",globeEthics:"These networks joined commerce and war to a company heavily involved with extractive activities outside Europe.",globeRouteVocMain:"Republic to Batavia",globeRouteVocMainDesc:"The principal outward VOC connection rounded the Cape, then used the westerlies across the southern Indian Ocean before turning towards the Sunda Strait and Batavia.",globeRouteBatavia:"Batavia, 1628–29",globeRouteBataviaDesc:"The VOC ship Batavia departed Texel for Java, rounded the Cape, sailed too far east on the southern-ocean corridor and wrecked at Houtman Abrolhos on 4 June 1629.",globeRouteJapan:"Batavia to Japan",globeRouteJapanDesc:"VOC trade with Japan was administered from Batavia, first through Hirado and later Dejima, with shipping passing north through the South China and East China seas.",globeRouteSpice:"Batavia to the Spice Islands",globeRouteSpiceDesc:"Batavia was the hub for recurrent VOC shipping east through the Java and Banda seas to Ambon and Banda, at the centre of a coercive spice monopoly.",globePeriodVocMain:"c. 1617–1795",globePeriodBatavia:"1628–1629",globePeriodJapan:"1609–1795",globePeriodSpice:"Seventeenth–eighteenth centuries",globePlaceTexel:"Texel roadstead",globePlaceCape:"Cape of Good Hope",globePlaceStPaul:"St Paul Island corridor",globePlaceSunda:"Sunda Strait",globePlaceBatavia:"Batavia (Jakarta)",globePlaceAbrolhos:"Houtman Abrolhos",globePlaceFormosa:"Formosa (Taiwan)",globePlaceDejima:"Hirado / Dejima",globePlaceAmbon:"Ambon",globePlaceBanda:"Banda Islands",settingP2:"The prominence of the Dutch East India Company in the economy led to both “the departure of thousands of men of marriageable age” and left-behind married women (Schmidt, 2025, p. 20). Travellers’ accounts “portrayed early modern Dutch women as economically active, entrepreneurial, independent, and dominant” relative to their foreign countries (Schmidt, 2025, p. 17).",settingP3:"To my knowledge, no quantitative work exists on why the economic autonomy of Dutch women seemed higher than in other countries at the time. Moreover, none of the reviewed literature has studied the effects of prolonged male absence caused by a peacetime context rather than a wartime context.",questionEyebrow:"Research question",questionH2:"Maritime-induced male absence and women’s economic autonomy",questionPull:"How did prolonged and permanent male absence resulting from voyages of the Dutch East India Company affect women’s economic autonomy in the early-modern Dutch Republic?",questionP1Html:"This presents an interesting historical <strong>natural experiment</strong> to study from a gendered perspective. While the general effects on the Dutch Republic’s economic prosperity are well known, little is known about the marginalised groups at home, and along gender lines, the group of interest is Dutch women.",questionPreviewHtml:"Through a continuous difference-in-differences design, I exploit variation in the literacy gender gap and seafarer departures across Dutch cities as measures for respectively women’s economic autonomy and maritime-induced male absence.",observeEyebrow:"Conceptual framework and data sources",observeH2:"The literacy gender gap as a measure of economic autonomy",observeP1Html:"To analyse women’s economic autonomy in the Dutch Republic, I use the gap between female and male literacy as an <strong>observable proxy outcome</strong>, which I argue is sufficiently representative of economic autonomy. Studying the literacy gender gap signals the relative economic position of women and men, which thus forms a crude yet sufficient proxy for economic autonomy.",observeP2:"Data on female and male literacy rates in the Dutch Republic are provided by Akçomak, Webbink, and ter Weel (2016), who aggregated literacy rates at the city level by differentiating between hand signatures and simple marks of brides and grooms in the Amsterdam Marriage Registers as a proxy for literacy. The place of former residence was registered in the records, allowing for literacy rates to be traced back to the cities from which the bride and the groom originated.",observeP3:"The ability to read and write was essential for attaining higher-level positions inside the maritime sector, which correspondingly would come with higher wages. More generally yet also more specifically for women, literacy also aided women in running or taking over businesses of their parent or spouse.",gapAlt:"Line chart of mean male and female literacy from 1600 to 1750; the shaded gender gap narrows from 33.2 to 25.6 percentage points",gapCaption:"The 32 Dutch cities start with a substantial literacy gender gap, which narrows over time primarily due to a mean increase in female literacy and a decrease in its variance across the cities, outpacing the concurrent increase in male literacy.",gapX:"Year",gapY:"Mean literacy (%)",gapMale:"Male literacy",gapFemale:"Female literacy",gap1600:"33.2 pp gap",gap1750:"25.6 pp gap",gapNote:"The shaded gap narrows over time",gapTooltipGap:"Gender gap",intensityEyebrow:"VOC departure intensity",intensityH2:"Data on literacy rates, VOC employee records and city populations",intensityPHtml:"To construct a continuous exposure measure to maritime-induced male absence, I use the enriched <strong>VOC seafarers dataset</strong>, which is constructed from 774,200 muster records of seafarers in the Dutch East India Company from 1633 to 1794 (Petram et al., 2024). I filter for disambiguated people and whether the place and date of their first departure is registered. Seafarer departures are aggregated into treatment intensity per city from 1633 to 1750 and normalised in relation to a city’s initial size.",mapAlt:"Stylized Dutch Republic map from thesis GIS outline, with Zuiderzee and Zeeland islands; circle size shows VOC departure intensity, Rotterdam highlighted",mapCaption:"The geographical distribution of the 32 cities shows that the sample is mostly evenly spread across the Dutch Republic. Most notably, Amsterdam’s literacy rates by gender are not present in the dataset. Nevertheless, the sample still contains a sufficient representation of western cities such as Rotterdam and Leiden, which benefited from the VOC.",intensityLegend:"VOC departure intensity",mapLower:"Lower",mapHigher:"Higher",mapTooltipIntensity:"VOC departure intensity",histAlt:"Histogram of VOC departure intensity across 32 Dutch cities, with Rotterdam in the right tail",histCaption:"Few of the 32 cities can be considered true control units or as good as untreated. All cities have some level of seafarer departures over a century-long period, explaining why binary distinctions between untreated and treated groups of cities are infeasible. A notable outlier is Rotterdam, which causes a right-skewed treatment distribution.",histX:"VOC departure intensity (departures ÷ 1600 population)",histY:"Number of cities",histCities:"Cities",histRotterdam:"Rotterdam bin",histTooltipCount:"Cities in bin",compareEyebrow:"Maritime-induced male absence and the literacy gender gap",compareH2:"Empirical strategy",compareP1:"To estimate the causal effect of seafarer departures on the literacy gender gap, I use a difference-in-differences approach that exploits variation in the number of seafarer departures across the Dutch Republic. By comparing changes in the literacy gender gap before and after the pre-treatment period of 1600 over two treatment periods, a three-period design allows for identification of the average treatment effect.",schematicAria:"Continuous DiD schematic",schematicOutcome:"Outcome",schematicOutcomeBody:"Change in literacy gender gap (female − male)",schematicExposure:"Exposure",schematicExposureBody:"VOC departures ÷ 1600 population",schematicHeld:"Held fixed",schematicHeldBody:"City FE, year FE, lon/lat × year",compareP2:"In contrast to the canonical design, I use a continuous treatment variable that allows for comparisons beyond binary distinctions between treated and untreated cities. A continuous difference-in-differences analysis compares across levels of treatment intensity, allowing for an analysis of the case where every city is at least minimally exposed to the VOC.",compareP3:"To make it more plausible that the conditional parallel trends assumption holds, I include interactions of longitude and latitude with year fixed effects to control for differential trends across cities, while also controlling for population growth to account for the influence of maritime commercial development on literacy gender gap trends.",methodsSummary:"Methods note: TWFE equation & gap sign",methodsP1:"Baseline form: literacy gender gapᵢ,ₜ = β (Dᵢ × Postₜ) + city FE + year FE + controls × year + εᵢ,ₜ. A flexible form replaces Post with year-specific interactions for 1675 and 1750 (1600 as baseline). Standard errors are clustered by city.",methodsP2:"Gap = female literacy − male literacy. Positive coefficients are discussed as a closing of women’s disadvantage (the gap becoming less negative / more equal), following the thesis convention.",estimatesEyebrow:"Maritime-induced male absence and the literacy gender gap",estimatesH2:"Results",estimatesPHtml:"When the effects of seafarer departures are able to vary over treatment periods, the estimated effect in 1750 is more pronounced compared to the baseline and statistically significant at the 5% level while controlling for longitude and latitude. A city in which a 25% equivalent of the 1600 baseline population flowed out to sea, equal to a one standard deviation increase in the treatment, experienced a <strong>2.84 percentage point decrease</strong> in the literacy gender gap.",statGapLabel:"Percentage point decrease in the literacy gender gap per 1 SD treatment increase",statGapNumber:"2.84",statFemaleLabel:"Of the 1750 treatment effect accounted for by female literacy",statFemaleNumber:"99.4%",statNLabel:"Dutch cities · 96 city–years",eventAlt:"Event-study plot of VOC departure intensity interactions for 1600, 1675, and 1750",eventCaption:"Point estimates with 95% confidence intervals of the flexible specifications with longitude and latitude controls, shown with and without population-growth controls.",esX:"Year",esY:"Literacy gender gap (pp)",esNote:"Preferred flexible TWFE · lon/lat × year FE · city-clustered 95% CIs",esBase:" (base)",esTooltipCoef:"Estimate",esTooltipInterval:"95% CI",decompIntro:"Composition of the literacy gender gap estimate in 1750:",decompAria:"Female versus male literacy",decompFemaleBtn:"Female literacy",decompMaleBtn:"Male literacy",decompFemaleNumber:"+11.30 pp",decompMaleNumber:"−0.07 pp",decompFemaleP:"The female literacy coefficient is statistically significant at the 5% level in 1750, accounting for 99.4% of the treatment effect on the gender gap.",decompMaleP:"Male literacy coefficients are not statistically significant in any treatment period, suggesting that female literacy is the sole significant driver behind the closing of the literacy gender gap.",fragileEyebrow:"Robustness checks",fragileH2:"Robustness checks and limitations",fragilePHtml:"After leaving out Rotterdam, a major outlier in the treatment intensity distribution, all treatment effects become statistically insignificant with far larger standard errors, confirming that the estimated treatment effects are highly driven by Rotterdam. This does not necessarily invalidate the previous results, but due to a lack of data availability gives <strong>little generalisable conclusions</strong> about the true strength of the average treatment effect.",limit1Html:"<strong>Small sample.</strong> The sample contains 32 Dutch cities, making support for the conditional parallel trends assumption hard to establish.",limit2Html:"<strong>Lack of pre-treatment periods.</strong> Pre-trend tests are impossible, making it difficult to argue that the parallel trends assumption is not violated.",limit3Html:"<strong>Limited time periods.</strong> With more available time periods associated with literacy rates and seafarer departures, heterogeneity-robust difference-in-differences estimators would be required to assess whether the findings remain robust.",limit4Html:"<strong>Commercial development.</strong> Population growth is controlled for to account for the influence of maritime commercial development on literacy gender gap trends, but consistent statistics for pre-treatment population growth trends do not exist.",limit5Html:"<strong>External validity.</strong> The data contain only Dutch cities, so the findings do not show whether the effects of seafarer departures are robust to variation in the religious status of cities.",readEyebrow:"Discussion and conclusion",readH2:"Discussion and conclusion",readPull:"The findings provide suggestive evidence in favour of a salient shock to the adult sex ratio, which divulged into consequences for domestic marriage markets and labour markets that encouraged women to acquire human capital.",readP1:"This thesis finds that VOC seafarer departures have a significant closing effect on the literacy gender gap. This effect is almost entirely driven by increases in female literacy rather than decreases in male literacy. It is robust to controlling for post-treatment population growth trends, but far less robust to dropping Rotterdam.",readP2:"This thesis also opens up normative discussions on colonialism and marginalised groups. Marginalised groups in the age of colonialism do not merely exist in colonised areas, but also exist in colonising states. The normative perception of these results depends on how disjointed the domestic effects of a colonial-linked shock should be analysed from the oppressive effects of colonialism abroad.",readP3:"Historical shocks can be equivalent to policy interventions: large-sweeping policy changes beneficial for women by, for example, affecting labour and marriage markets, can improve their economic outcomes. The study of historical shocks provides a method through which historical events can offer lessons for today’s policy.",readP4:"Overall, this thesis provides valuable contributions to the economic history literature, implications for normative discussions beyond the scope of what is normally considered in the economic science and indirect insights for contemporary policy design. Through the study of a historical setting, this thesis links itself to important philosophical and policy debates today.",footerTitle:"Women’s economic autonomy in the Dutch Republic and maritime-induced male absence",footerByline:"Take Watanabe · Philosophy, Politics and Economics · Vrije Universiteit Amsterdam · 22nd May 2026",footerPdf:"Thesis PDF",footerTop:"Back to top",footerRefs:"References",footerCiteNote:"Sources cited in this narrative."},nl:{metaTitle:"Economische autonomie van vrouwen in de Nederlandse Republiek en de door de VOC-veroorzaakte afwezigheid van mannen · Take Watanabe",metaDescription:"Deze scriptie onderzoekt het causale effect van maritiem veroorzaakte afwezigheid van mannen op de economische autonomie van vrouwen in de vroegmoderne Nederlandse Republiek.",navAria:"Hoofdstukken",langAria:"Taal",navMenuOpen:"Open sectiemenu",navMenuClose:"Sluit sectiemenu",navBrand:"Take Watanabe",navTitle:"Economische autonomie van vrouwen in de Republiek en de door de VOC-veroorzaakte afwezigheid van mannen",navSetting:"Inleiding",navQuestion:"Onderzoeksvraag",navObserve:"Conceptueel kader en databronnen",navIntensity:"Gegevens en behandelingsintensiteit",navCompare:"Empirische strategie",navEstimates:"Resultaten",navFragile:"Robuustheidstoetsen",navRead:"Discussie en conclusie",heroBrand:"Take Watanabe",heroTitle:"Economische autonomie van vrouwen in de Nederlandse Republiek en de door de VOC-veroorzaakte afwezigheid van mannen",heroLede:"Deze scriptie levert ondersteunend bewijs voor de hypothese dat de economische autonomie van vrouwen in de Nederlandse Republiek positief werd beïnvloed door maritiem veroorzaakte afwezigheid van mannen.",heroBegin:"Volg het bewijs",heroPdf:"Download PDF",heroFindingsAria:"Wat het bewijs suggereert",heroFindingsEyebrow:"Samenvatting",heroEstimateAria:"2,84 procentpunt: geschatte kleinere geletterdheidskloof in 1750 per één standaarddeviatie hogere VOC-vertrekintensiteit, met geografische controles",heroEstimateNumber:"2,84",heroEstimateUnit:"procentpunt",heroEstimateLabel:"Afname van de geletterdheidskloof per één standaarddeviatie meer vertrek van zeevarenden",heroEstimateQualifier:"1750 · rekening houdend met lengte- en breedtegraad",heroFemaleAria:"99,4 procent van het behandelingseffect op de genderkloof in 1750 wordt verklaard door vrouwelijke geletterdheid",heroFemaleNumber:"99,4%",heroFemaleLabel:"van het behandelingseffect via vrouwelijke geletterdheid",heroSampleAria:"32 steden en 96 stadsjaren in de steekproef",heroSampleLabel:"steden · 96 stadsjaren",heroCaveatAria:"De resultaten zijn zeer robuust wanneer rekening wordt gehouden met bevolkingsgroei en minder robuust bij een weglaattoets",heroCaveatLabel:"Robuustheid",heroCaveatText:"De resultaten zijn zeer robuust wanneer rekening wordt gehouden met bevolkingsgroei en minder robuust bij een weglaattoets.",settingEyebrow:"Inleiding",settingH2:"De opkomst van de Republiek en overzeese handel",settingP1:"De opkomst van de Republiek in de zeventiende eeuw ging hand in hand met de bloei van de overzeese handel. Deze bloei werd gedreven door lange en gevaarlijke reizen uitgevoerd door de Verenigde Oostindische Compagnie (VOC), die nodig waren om zowel de onafhankelijkheidsoorlog tegen het Spaanse Rijk te financieren als de Spaanse en Portugese dominantie in Azië te bestrijden. De opkomst van de VOC vormde uiteindelijk de basis voor de Gouden Eeuw.",globeAlt:"Interactieve wereldbol met gereconstrueerde vaarroutes en gedocumenteerde reizen van de VOC",globeCaption:"Geselecteerde VOC-verbindingen in de zeventiende en achttiende eeuw. Havens zijn met bronnen onderbouwd; de lijnen ertussen reconstrueren historisch aangetoonde vaarcorridors en zijn geen exacte scheepstrajecten.",globeMetaWorld:"Wereld · 17e–18e eeuw",globeMetaProjection:"Orthografisch",globeInstruction:"Sleep horizontaal om te draaien · gebruik pijltjestoetsen bij focus",globeRoutesLabel:"Kies een route",globePause:"Rotatie pauzeren",globeResume:"Rotatie hervatten",globeZoomIn:"Inzoomen",globeZoomOut:"Uitzoomen",globeTypeCorridor:"Terugkerende corridor",globeTypeVoyage:"Gedocumenteerde reis",globePeriodLabel:"Periode",globeStopsLabel:"Gedocumenteerde plaatsen",globeSourcesLabel:"Historische bronnen",globeReconstruction:"Toelichting op de route: gedocumenteerde plaatsen zijn verbonden via gereconstrueerde vaarpunten op basis van historische routes en heersende winden; de lijn geeft geen bewaard traject van dag tot dag weer.",globeEthics:"Deze netwerken verbonden handel en oorlog met een compagnie die buiten Europa sterk betrokken was bij economische uitbuiting.",globeRouteVocMain:"Republiek naar Batavia",globeRouteVocMainDesc:"De voornaamste uitgaande VOC-verbinding rondde de Kaap en gebruikte daarna westenwinden over de zuidelijke Indische Oceaan, voordat zij naar Straat Soenda en Batavia afboog.",globeRouteBatavia:"Batavia, 1628–29",globeRouteBataviaDesc:"Het VOC-schip Batavia vertrok van Texel naar Java, rondde de Kaap, voer te ver oostwaarts op de zuidelijke oceaancorridor en verging op 4 juni 1629 bij de Houtman Abrolhos.",globeRouteJapan:"Batavia naar Japan",globeRouteJapanDesc:"De VOC-handel met Japan werd vanuit Batavia bestuurd, eerst via Hirado en later Dejima, met scheepvaart noordwaarts door de Zuid- en Oost-Chinese Zee.",globeRouteSpice:"Batavia naar de Specerij-eilanden",globeRouteSpiceDesc:"Batavia was het knooppunt voor terugkerende VOC-scheepvaart oostwaarts door de Java- en Bandazee naar Ambon en Banda, het centrum van een met dwang gehandhaafd specerijenmonopolie.",globePeriodVocMain:"ca. 1617–1795",globePeriodBatavia:"1628–1629",globePeriodJapan:"1609–1795",globePeriodSpice:"Zeventiende–achttiende eeuw",globePlaceTexel:"Rede van Texel",globePlaceCape:"Kaap de Goede Hoop",globePlaceStPaul:"Corridor langs Île Saint-Paul",globePlaceSunda:"Straat Soenda",globePlaceBatavia:"Batavia (Jakarta)",globePlaceAbrolhos:"Houtman Abrolhos",globePlaceFormosa:"Formosa (Taiwan)",globePlaceDejima:"Hirado / Dejima",globePlaceAmbon:"Ambon",globePlaceBanda:"Banda-eilanden",settingP2:"De prominente rol van de VOC in de economie leidde tot het vertrek van duizenden mannen van huwbare leeftijd en tot gehuwde vrouwen die achterbleven (Schmidt, 2025, p. 20). Reisverslagen beschreven vroegmoderne Nederlandse vrouwen als economisch actief, ondernemend, onafhankelijk en dominant ten opzichte van vrouwen in andere landen (Schmidt, 2025, p. 17).",settingP3:"Voor zover ik weet bestaat er geen kwantitatief onderzoek naar waarom de economische autonomie van Nederlandse vrouwen destijds groter leek dan in andere landen. Bovendien onderzocht geen van de besproken studies de effecten van langdurige afwezigheid van mannen in vredestijd in plaats van oorlogstijd.",questionEyebrow:"Onderzoeksvraag",questionH2:"Maritiem veroorzaakte afwezigheid van mannen en economische autonomie van vrouwen",questionPull:"Hoe beïnvloedde de langdurige en permanente afwezigheid van mannen, veroorzaakt door reizen van de Verenigde Oostindische Compagnie, de economische autonomie van vrouwen in de vroegmoderne Republiek?",questionP1Html:"Dit vormt een interessant historisch <strong>natuurlijk experiment</strong> om langs genderlijnen te bestuderen. Hoewel de bijdrage van de VOC aan de bloei van de Republiek vaststaat, is er weinig bekend over de positie van onderbelichte groepen in eigen land, waaronder Nederlandse vrouwen die in de voorheen katholieke Nederlanden weinig te zeggen hadden in brede zin.",questionPreviewHtml:"Met een continue difference-in-differences-opzet benut ik verschillen tussen Nederlandse steden in de geletterdheidskloof en het vertrek van zeevarenden. Deze dienen als maatstaven voor respectievelijk de economische autonomie van vrouwen en de maritiem veroorzaakte afwezigheid van mannen.",observeEyebrow:"Conceptueel kader en databronnen",observeH2:"De geletterdheidskloof als maatstaf voor economische autonomie",observeP1Html:"Om de economische autonomie van vrouwen in de Republiek te analyseren, gebruik ik het verschil tussen vrouwelijke en mannelijke geletterdheid als een <strong>waarneembare proxyvariabele</strong>. De geletterdheidskloof weerspiegelt de relatieve economische positie van vrouwen en mannen en biedt daarmee een ruwe, maar bruikbare benadering van economische autonomie.",observeP2:"De gegevens over vrouwelijke en mannelijke geletterdheid zijn afkomstig van Akçomak, Webbink en ter Weel (2016). Zij aggregeerden geletterdheid per stad door handtekeningen en eenvoudige merktekens van bruiden en bruidegoms in de Amsterdamse huwelijksregisters te onderscheiden. De voormalige woonplaats werd geregistreerd, waardoor geletterdheid kon worden herleid tot de herkomststeden van bruid en bruidegom.",observeP3:"Kunnen lezen en schrijven was essentieel voor hogere functies in de maritieme sector, die hogere lonen opleverden. Voor vrouwen hielp geletterdheid bovendien bij het leiden of overnemen van het bedrijf van een ouder of echtgenoot.",gapAlt:"Lijndiagram van gemiddelde mannelijke en vrouwelijke geletterdheid van 1600 tot 1750; de gearceerde genderkloof vernauwt van 33,2 naar 25,6 procentpunten",gapCaption:"De 32 Nederlandse steden kenden aanvankelijk een aanzienlijke geletterdheidskloof. Die werd vooral kleiner doordat de gemiddelde vrouwelijke geletterdheid steeg en de spreiding daarvan tussen steden afnam, terwijl de mannelijke geletterdheid minder snel steeg.",gapX:"Jaar",gapY:"Gemiddelde geletterdheid (%)",gapMale:"Mannelijke geletterdheid",gapFemale:"Vrouwelijke geletterdheid",gap1600:"33,2 pp kloof",gap1750:"25,6 pp kloof",gapNote:"De gearceerde kloof vernauwt over tijd",gapTooltipGap:"Genderkloof",intensityEyebrow:"VOC-vertrekintensiteit",intensityH2:"Gegevens over geletterdheid, VOC-werknemers en stadsbevolking",intensityPHtml:"Om een continue blootstellingsmaat voor maritiem veroorzaakte afwezigheid van mannen samen te stellen, gebruik ik het verrijkte <strong>VOC-opvarendenbestand</strong>, opgebouwd uit 774.200 monsterrolregistraties van VOC-zeevarenden van 1633 tot 1794 (Petram et al., 2024). Ik selecteer eenduidig geïdentificeerde personen met een geregistreerde plaats en datum van eerste vertrek. Het vertrek van zeevarenden wordt per stad samengevoegd van 1633 tot 1750 en genormaliseerd ten opzichte van de oorspronkelijke omvang van de stad.",mapAlt:"Gestileerde Republiekkaart naar thesis-GIS, met Zuiderzee en Zeeuwse eilanden; cirkelgrootte toont VOC-vertrekintensiteit, Rotterdam gemarkeerd",mapCaption:"De geografische spreiding van de 32 steden toont dat de steekproef grotendeels gelijkmatig over de Republiek is verdeeld. Vooral de geletterdheidscijfers van Amsterdam ontbreken. Toch bevat de steekproef voldoende westelijke steden, zoals Rotterdam en Leiden, die van de VOC profiteerden.",intensityLegend:"VOC-vertrekintensiteit",mapLower:"Lager",mapHigher:"Hoger",mapTooltipIntensity:"VOC-vertrekintensiteit",histAlt:"Histogram van VOC-vertrekintensiteit over 32 Nederlandse steden, met Rotterdam in de rechterstaart",histCaption:"Weinig van de 32 steden kunnen als echte vergelijkingseenheid of vrijwel onbehandeld worden beschouwd. Alle steden kennen over een periode van een eeuw enig vertrek van zeevarenden, waardoor binaire indelingen in behandelde en onbehandelde steden niet haalbaar zijn. Rotterdam is een opvallende uitschieter die de verdeling rechtsscheef maakt.",histX:"VOC-vertrekintensiteit (vertrekken ÷ bevolking 1600)",histY:"Aantal steden",histCities:"Steden",histRotterdam:"Klasse met Rotterdam",histTooltipCount:"Steden in deze klasse",compareEyebrow:"Maritiem veroorzaakte afwezigheid van mannen en de geletterdheidskloof",compareH2:"Empirische strategie",compareP1:"Om het causale effect van het vertrek van zeevarenden op de geletterdheidskloof te schatten, gebruik ik een difference-in-differences-opzet die verschillen in het aantal vertrekken tussen steden benut. Door veranderingen vóór en na het voorbehandelingsjaar 1600 over twee behandelingsperioden te vergelijken, kan een drieperiodenopzet het gemiddelde behandelingseffect vaststellen.",schematicAria:"Schematische weergave van continue DiD",schematicOutcome:"Uitkomst",schematicOutcomeBody:"Verandering in geletterdheidskloof (vrouw − man)",schematicExposure:"Blootstelling",schematicExposureBody:"VOC-vertrekken ÷ bevolking 1600",schematicHeld:"Constant gehouden",schematicHeldBody:"Vaste stads- en jaareffecten, lengte-/breedtegraad × jaar",compareP2:"In tegenstelling tot de gebruikelijke opzet gebruik ik een continue behandelingsvariabele, zodat de vergelijking niet beperkt blijft tot een tweedeling tussen behandelde en onbehandelde steden. Een continue difference-in-differences-analyse vergelijkt behandelingsintensiteiten en maakt bovendien een analyse mogelijk in het geval waarin elke stad in enige mate aan de VOC is blootgesteld.",compareP3:"Om de aanname van conditionele parallelle trends aannemelijker te maken, neem ik interacties op tussen lengte- en breedtegraad en vaste jaareffecten. Zo houd ik rekening met uiteenlopende trends tussen steden. Ook houd ik rekening met bevolkingsgroei om de invloed van maritiem-gedreven stedelijke ontwikkeling op de geletterdheidskloof mee te nemen.",methodsSummary:"Methodennotitie: TWFE-vergelijking en teken van de kloof",methodsP1:"Basisvorm: geletterdheidskloofᵢ,ₜ = β (Dᵢ × Postₜ) + stad-FE + jaar-FE + controlevariabelen × jaar + εᵢ,ₜ. Een flexibele vorm vervangt Post door jaarspecifieke interacties voor 1675 en 1750 (1600 als basislijn). Standaardfouten zijn geclusterd per stad.",methodsP2:"Kloof = vrouwelijke − mannelijke geletterdheid. Positieve coëfficiënten worden besproken als een verkleining van het nadeel voor vrouwen (de kloof minder negatief / gelijker), volgens de conventie van de scriptie.",estimatesEyebrow:"Maritiem veroorzaakte afwezigheid van mannen en de geletterdheidskloof",estimatesH2:"Resultaten",estimatesPHtml:"Wanneer de effecten van het vertrek van zeevarenden tussen behandelingsperioden mogen variëren, is het geschatte effect in 1750 sterker dan in de basisspecificatie en statistisch significant op het 5%-niveau, waarbij rekening is gehouden met lengte- en breedtegraad. Een vertrek ter grootte van 25% van de bevolking in 1600—gelijk aan één standaarddeviatie hogere behandelingsintensiteit—hing samen met een <strong>afname van 2,84 procentpunt</strong> in de geletterdheidskloof.",statGapNumber:"2,84",statGapLabel:"Procentpunt afname in de geletterdheidskloof per één standaarddeviatie hogere behandelingsintensiteit",statFemaleNumber:"99,4%",statFemaleLabel:"Van het behandelingseffect in 1750 verklaard door vrouwelijke geletterdheid",statNLabel:"Nederlandse steden · 96 stadsjaren",eventAlt:"Eventstudie van interacties met de VOC-vertrekintensiteit voor 1600, 1675 en 1750",eventCaption:"Puntschattingen met 95%-betrouwbaarheidsintervallen van de flexibele specificaties, waarbij rekening is gehouden met lengte- en breedtegraad en, afhankelijk van de specificatie, met bevolkingsgroei.",esX:"Jaar",esY:"Geletterdheidskloof (pp)",esNote:"Flexibele TWFE-voorkeursspecificatie · lengte-/breedtegraad × vaste jaareffecten · per stad geclusterde 95%-BI’s",esBase:" (basis)",esTooltipCoef:"Schatting",esTooltipInterval:"95%-BI",decompIntro:"Samenstelling van de geschatte geletterdheidskloof in 1750:",decompAria:"Vrouwelijke versus mannelijke geletterdheid",decompFemaleBtn:"Vrouwelijke geletterdheid",decompMaleBtn:"Mannelijke geletterdheid",decompFemaleNumber:"+11,30 pp",decompMaleNumber:"−0,07 pp",decompFemaleP:"De coëfficiënt voor vrouwelijke geletterdheid is in 1750 statistisch significant op het 5%-niveau en verklaart 99,4% van het behandelingseffect op de genderkloof.",decompMaleP:"Coëfficiënten voor mannelijke geletterdheid zijn in geen enkele behandelingsperiode statistisch significant. Dit wijst erop dat de kleinere geletterdheidskloof uitsluitend samenhangt met de toename van vrouwelijke geletterdheid.",fragileEyebrow:"Robuustheidstoetsen",fragileH2:"Robuustheidstoetsen en beperkingen",fragilePHtml:"Na het weglaten van Rotterdam, een grote uitschieter in de verdeling van de behandelingsintensiteit, zijn alle behandelingseffecten niet langer statistisch significant en nemen de standaardfouten sterk toe. De geschatte effecten zijn dus in belangrijke mate aan Rotterdam toe te schrijven. Dit maakt de eerdere resultaten niet noodzakelijk ongeldig, maar door de beperkte beschikbaarheid van gegevens zijn <strong>nauwelijks algemeen geldende conclusies</strong> mogelijk over de werkelijke omvang van het gemiddelde behandelingseffect.",limit1Html:"<strong>Kleine steekproef.</strong> De steekproef bevat 32 Nederlandse steden, waardoor de aanname van conditionele parallelle trends moeilijk te onderbouwen is.",limit2Html:"<strong>Gebrek aan voorbehandelingsperioden.</strong> Toetsen op voorafgaande trends zijn onmogelijk, waardoor moeilijk kan worden betoogd dat de parallelle-trendsaanname niet wordt geschonden.",limit3Html:"<strong>Beperkt aantal perioden.</strong> Met meer perioden voor geletterdheid en het vertrek van zeevarenden zouden heterogeniteitsrobuuste difference-in-differences-schatters nodig zijn om te beoordelen of de bevindingen standhouden.",limit4Html:"<strong>Commerciële ontwikkeling.</strong> In de analyse wordt rekening gehouden met bevolkingsgroei om de invloed van maritiem-gedreven stedelijke ontwikkeling te ondervangen, maar vergelijkbare statistieken over bevolkingsgroei vóór behandeling bestaan niet.",limit5Html:"<strong>Externe validiteit.</strong> De gegevens bevatten alleen Nederlandse steden. Daardoor blijkt niet of verschillen in de religieuze status van steden van invloed zijn op het geschatte effect van het vertrek van zeevarenden.",readEyebrow:"Discussie en conclusie",readH2:"Discussie en conclusie",readPull:"De bevindingen wijzen op een opvallende verandering in de verhouding tussen volwassen mannen en vrouwen. Die werkte door op binnenlandse huwelijks- en arbeidsmarkten en zette vrouwen ertoe aan in menselijk kapitaal te investeren.",readP1:"De resultaten wijzen erop dat het vertrek van VOC-zeevarenden de geletterdheidskloof significant verkleint. Dit effect is bijna volledig toe te schrijven aan een stijging van de vrouwelijke geletterdheid en niet aan een daling van de mannelijke geletterdheid. Het resultaat is robuust wanneer rekening wordt gehouden met bevolkingsgroei na behandeling, maar veel minder robuust wanneer Rotterdam wordt weggelaten.",readP2:"Deze scriptie opent ook een normatieve discussie over kolonialisme en onderbelichte groepen. Zulke groepen bestonden in het koloniale tijdperk niet alleen in gekoloniseerde gebieden, maar ook in koloniserende landen. De normatieve beoordeling hangt af van de vraag of en in hoeverre binnenlandse gevolgen van een koloniale schok afzonderlijk kunnen worden beoordeeld van de onderdrukkende gevolgen van kolonialisme in het buitenland.",readP3:"Historische schokken kunnen overeenkomsten vertonen met beleidsingrepen. Grootschalige beleidsveranderingen die vrouwen ten goede komen door bijvoorbeeld arbeids- en huwelijksmarkten te beïnvloeden, kunnen hun economische positie verbeteren. Historische gebeurtenissen kunnen zo lessen bieden voor het huidige beleid.",readP4:"Over het geheel genomen draagt deze scriptie bij aan de economisch-historische literatuur, aan normatieve discussies die verder reiken dan de gebruikelijke economische analyse en aan de vormgeving van hedendaags beleid. Door deze historische context te bestuderen, sluit de scriptie aan bij belangrijke filosofische en beleidsdebatten van vandaag.",footerTitle:"Economische autonomie van vrouwen in de Republiek en de door de VOC-veroorzaakte afwezigheid van mannen",footerByline:"Take Watanabe · Philosophy, Politics and Economics · Vrije Universiteit Amsterdam · 22 mei 2026",footerPdf:"Scriptie-PDF",footerTop:"Terug naar boven",footerRefs:"Bronnen",footerCiteNote:"Bronnen die op deze website worden genoemd."}},qt="en",zn=["en","nl"],a1=[{key:"akcomak2016",html:'Akçomak, İ. S., Webbink, D., & ter Weel, B. (2016). Why Did the Netherlands Develop So Early? The Legacy of the Brethren of the Common Life. <em>The Economic Journal, 126</em>(593), 821–860. <a href="https://doi.org/10.1111/ecoj.12193" target="_blank" rel="noopener noreferrer">https://doi.org/10.1111/ecoj.12193</a>',sort:"Akçomak, İ. S., Webbink, D., & ter Weel, B.",year:"2016"},{key:"petram2024",html:`Petram, L., Koolen, M., Wevers, M., van Koert, R., & van Lottum, J. (2024). <em>The Dutch East India Company's eighteenth-century workforce: An enriched data collection</em> [Data set]. Zenodo. <a href="https://doi.org/10.5281/zenodo.10599528" target="_blank" rel="noopener noreferrer">https://doi.org/10.5281/zenodo.10599528</a>`,sort:"Petram, L., Koolen, M., Wevers, M., van Koert, R., & van Lottum, J.",year:"2024"},{key:"schmidt2025",html:'Schmidt, A. (2025). Women and Work in the Dutch Republic. <em>Early Modern Low Countries, 9</em>(1), 14–33. <a href="https://doi.org/10.51750/emlc23005" target="_blank" rel="noopener noreferrer">https://doi.org/10.51750/emlc23005</a>',sort:"Schmidt, A.",year:"2025"}],s1="46cb769847",D={sea:"#23443e",seaMid:"#315b53",seaSoft:"#6e8a82",parchment:"#f5f2eb",parchmentDeep:"#cbc7bd",ink:"#1a1a17",inkMuted:"#56564f",ochre:"#9b4d35",white:"#fbfaf6"},ye="'IBM Plex Sans', 'Helvetica Neue', Arial, sans-serif";function re(){return window.matchMedia("(prefers-reduced-motion: reduce)").matches}functio